styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap');

.dgs-llm-page,
.dgs-llm-page *,
.dgs-llm-page *::before,
.dgs-llm-page *::after {
  box-sizing: border-box;
}

.dgs-llm-page * {
  margin-top: 0;
}

.dgs-llm-page {
  --brand-magenta: #E91E8C;
  --brand-purple: #B91E8C;
  --brand-orange: #FF6B35;
  --gradient-brand: linear-gradient(135deg, var(--brand-magenta) 0%, var(--brand-purple) 50%, var(--brand-orange) 100%);
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: #000000;
  color: #ffffff;
  line-height: 1.6;
  overflow: hidden;
}


.dgs-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}


/* Full-width fix for Elementor boxed/720px container issue */
.dgs-llm-page {
  width: 100vw !important;
  max-width: 100vw !important;
  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;
}

.dgs-container,
.dgs-hero-container,
.dgs-content-wrapper,
.dgs-section-header,
.dgs-final-cta-container,
.dgs-cta-content,
.llm-upgrade .w,
.llm-upgrade .ws {
  max-width: min(1500px, calc(100vw - 48px)) !important;
  width: 100%;
}

.dgs-content-wrapper > p,
.dgs-content-wrapper > h2,
.dgs-content-wrapper > h3,
.dgs-content-wrapper > ol,
.dgs-content-wrapper > ul {
  max-width: 1180px;
  margin-left: auto;
  margin-right: auto;
}

.llm-upgrade .sec,
.dgs-content-section,
.dgs-pillars-section,
.dgs-city-section,
.dgs-awards-section,
.dgs-faq-section,
.dgs-cta-section,
.dgs-final-cta,
.dgs-clients {
  width: 100%;
}

@media (max-width: 768px) {
  .dgs-container,
  .dgs-hero-container,
  .dgs-content-wrapper,
  .dgs-section-header,
  .dgs-final-cta-container,
  .dgs-cta-content,
  .llm-upgrade .w,
  .llm-upgrade .ws {
    max-width: calc(100vw - 32px) !important;
  }
}

/* Animations */
@keyframes gradientPulse {
  0%, 100% { background-position: 0% 50%; filter: brightness(1); }
  50% { background-position: 100% 50%; filter: brightness(1.3); }
}

@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 1; box-shadow: 0 0 0 0 rgba(233, 30, 140, 0.7); }
  50% { transform: scale(1.3); opacity: 0.8; box-shadow: 0 0 0 10px rgba(233, 30, 140, 0); }
}

@keyframes float {
  0%, 100% { transform: translate(0, 0) scale(1) rotate(0deg); }
  33% { transform: translate(40px, -40px) scale(1.15) rotate(5deg); }
  66% { transform: translate(-30px, 30px) scale(0.9) rotate(-5deg); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(40px); }
  to { opacity: 1; transform: translateY(0); }
}

.dgs-gradient-text {
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
  background-size: 400% 400%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  display: inline-block;
  animation: gradientPulse 4s ease infinite;
}

/* Hero */
.dgs-llm-hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 110px 20px 82px;
}

.dgs-hero-container {
  max-width: 1120px;
  margin: 0 auto;
  text-align: center;
  position: relative;
  z-index: 2;
}

.dgs-elite-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 8px 32px 0 rgba(233, 30, 140, 0.15);
  border-radius: 50px;
  padding: 12px 28px;
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 34px;
  animation: fadeInUp 0.6s ease-out;
  letter-spacing: 0.5px;
}

.dgs-pulse-dot {
  width: 10px;
  height: 10px;
  background: var(--gradient-brand);
  border-radius: 50%;
  animation: pulse 2s ease-in-out infinite;
}

.dgs-hero-title {
  font-size: clamp(42px, 7vw, 72px);
  font-weight: 700;
  line-height: 1.16;
  margin-bottom: 24px;
  animation: fadeInUp 0.8s ease-out 0.2s backwards;
}

.dgs-hero-description {
  font-size: clamp(18px, 2.3vw, 22px);
  color: rgba(255, 255, 255, 0.8);
  max-width: 930px;
  margin: 0 auto 36px;
  line-height: 1.8;
  animation: fadeInUp 1s ease-out 0.4s backwards;
}

.dgs-updated-line {
  margin: -10px auto 34px;
  font-size: 14px;
  color: rgba(255,255,255,0.58);
  letter-spacing: .02em;
  animation: fadeInUp 1.05s ease-out 0.45s backwards;
}

.dgs-updated-line strong {
  color: #ffffff;
  font-weight: 600;
}

.dgs-trust-badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 14px;
  margin-bottom: 38px;
  animation: fadeInUp 1.1s ease-out 0.5s backwards;
}

.dgs-trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.85);
  padding: 8px 18px;
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 30px;
}

.dgs-trust-item::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--gradient-brand);
  border-radius: 50%;
}

.dgs-hero-cta {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 18px;
  animation: fadeInUp 1.2s ease-out 0.6s backwards;
}

.dgs-btn-primary,
.dgs-btn-secondary,
.dgs-btn-whatsapp {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  padding: 18px 34px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 17px;
  text-decoration: none;
  transition: all 0.3s ease;
  border: 1px solid transparent;
  position: relative;
  overflow: hidden;
  color: #ffffff !important;
}

.dgs-btn-primary {
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
  background-size: 400% 400%;
  color: #ffffff;
  animation: gradientPulse 4s ease infinite;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.3);
}

.dgs-btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 40px rgba(233, 30, 140, 0.4);
}

.dgs-btn-secondary {
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
}

.dgs-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--brand-magenta);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
}

.dgs-btn-whatsapp {
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
}

.dgs-btn-whatsapp:hover {
  background: rgba(37, 211, 102, 0.15);
  border-color: #25D366;
  box-shadow: 0 8px 32px rgba(37, 211, 102, 0.2);
}

.dgs-hero-bg-element {
  position: absolute;
  border-radius: 50%;
  filter: blur(140px);
  opacity: 0.15;
}

.dgs-hero-bg-1 {
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--brand-magenta) 0%, transparent 70%);
  top: -150px;
  left: -150px;
  animation: float 25s ease-in-out infinite, gradientPulse 8s ease infinite;
}

.dgs-hero-bg-2 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--brand-purple) 0%, transparent 70%);
  top: 40%;
  right: -150px;
  animation: float 30s ease-in-out infinite 5s, gradientPulse 10s ease infinite;
}

.dgs-hero-bg-3 {
  width: 700px;
  height: 700px;
  background: radial-gradient(circle, var(--brand-orange) 0%, transparent 70%);
  bottom: -250px;
  left: 35%;
  animation: float 35s ease-in-out infinite 10s, gradientPulse 12s ease infinite;
}

/* Clients */
.dgs-clients {
  padding: 58px 20px;
  background: rgba(255, 255, 255, 0.01);
  backdrop-filter: blur(10px);
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.dgs-clients-title {
  text-align: center;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 2.5px;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 34px;
  font-weight: 500;
}

.dgs-clients-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 34px;
  align-items: center;
  max-width: 1100px;
  margin: 0 auto;
}

.dgs-client-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.72;
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.dgs-client-logo:hover {
  opacity: 1;
  transform: scale(1.05);
}

.dgs-client-logo img {
  max-width: 132px;
  height: auto;
}



/* Awards Section */
.dgs-awards-section {
  padding: 82px 20px;
  background: rgba(255, 255, 255, 0.01);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.dgs-awards-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  max-width: 1180px;
  margin: 0 auto;
}

.dgs-award-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  transition: all 0.35s ease;
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.dgs-award-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--gradient-brand);
  opacity: 0.9;
  z-index: 2;
}

.dgs-award-card:hover {
  transform: translateY(-7px);
  border-color: rgba(233,30,140,0.35);
  box-shadow: 0 24px 70px rgba(233,30,140,0.14);
}

.dgs-award-image {
  height: 410px;
  padding: 10px 10px 0;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dgs-award-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  image-rendering: auto;
}

.dgs-award-body {
  padding: 24px 24px 28px;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.dgs-award-tag {
  display: inline-block;
  padding: 5px 12px;
  border-radius: 99px;
  background: rgba(233,30,140,0.09);
  border: 1px solid rgba(233,30,140,0.22);
  color: rgba(255,255,255,0.78);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.dgs-award-title {
  font-size: 19px;
  line-height: 1.35;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 8px;
}

.dgs-award-desc {
  font-size: 14.5px;
  line-height: 1.7;
  color: rgba(255,255,255,0.68);
  margin: 0;
}

@media (max-width: 1024px) {
  .dgs-awards-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .dgs-awards-section {
    padding: 70px 20px;
  }

  .dgs-awards-grid {
    grid-template-columns: 1fr;
  }

  .dgs-award-image {
    height: 360px;
  }
}
/* Content */
.dgs-content-section {
  padding: 82px 20px;
}

.dgs-content-section.alt-bg {
  background: rgba(255, 255, 255, 0.01);
}

.dgs-content-wrapper {
  max-width: 1000px;
  margin: 0 auto;
}

.dgs-content-wrapper h2 {
  font-size: clamp(32px, 5vw, 50px);
  font-weight: 700;
  margin-bottom: 24px;
  line-height: 1.2;
}

.dgs-content-wrapper h3 {
  font-size: clamp(24px, 4vw, 34px);
  font-weight: 700;
  margin-bottom: 18px;
  margin-top: 44px;
  line-height: 1.3;
}

.dgs-content-wrapper p {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.8;
  margin-bottom: 18px;
}

.dgs-content-wrapper strong {
  color: #ffffff;
  font-weight: 600;
}

.dgs-content-wrapper a,
.dgs-inline-link {
  color: #ffffff;
  text-decoration: none;
  border-bottom: 1px solid rgba(255,255,255,0.25);
  transition: all 0.25s ease;
}

.dgs-content-wrapper a:hover,
.dgs-inline-link:hover {
  color: #ffffff;
  border-bottom-color: var(--brand-magenta);
  box-shadow: inset 0 -1px 0 rgba(233,30,140,0.35);
}

.dgs-content-wrapper ul {
  list-style: none;
  padding: 0;
  margin: 24px 0;
}

.dgs-content-wrapper ul li {
  padding: 10px 0 10px 28px;
  position: relative;
  color: rgba(255, 255, 255, 0.8);
  font-size: 17px;
  line-height: 1.7;
}

.dgs-content-wrapper ul li:before {
  content: "";
  position: absolute;
  left: 0;
  top: 20px;
  width: 14px;
  height: 2px;
  background: var(--gradient-brand);
}


/* Local SEO City Cards */
.dgs-city-section {
  padding: 82px 20px;
  background: rgba(255, 255, 255, 0.01);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.dgs-city-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  max-width: 1180px;
  margin: 0 auto;
}

.dgs-city-card {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 16px;
  padding: 26px 22px;
  position: relative;
  overflow: hidden;
  transition: all 0.35s ease;
  min-height: 220px;
}

.dgs-city-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--gradient-brand);
  opacity: 0;
  transition: opacity 0.35s ease;
}

.dgs-city-card::after {
  content: '';
  position: absolute;
  width: 120px;
  height: 120px;
  right: -45px;
  bottom: -55px;
  background: radial-gradient(circle, rgba(233,30,140,0.16) 0%, transparent 68%);
  filter: blur(8px);
  opacity: 0;
  transition: opacity 0.35s ease;
}

.dgs-city-card:hover {
  transform: translateY(-6px);
  border-color: rgba(233,30,140,0.34);
  background: rgba(255, 255, 255, 0.05);
  box-shadow: 0 18px 52px rgba(233, 30, 140, 0.12);
}

.dgs-city-card:hover::before,
.dgs-city-card:hover::after {
  opacity: 1;
}

.dgs-city-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.66);
  margin-bottom: 12px;
}

.dgs-city-tag::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gradient-brand);
}

.dgs-city-title {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.28;
  color: #ffffff;
  margin-bottom: 10px;
}

.dgs-city-desc {
  font-size: 14.5px;
  line-height: 1.72;
  color: rgba(255,255,255,0.68);
  margin-bottom: 16px;
}

.dgs-city-keywords {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

.dgs-city-keywords span {
  font-size: 11px;
  line-height: 1;
  padding: 7px 9px;
  border-radius: 99px;
  color: rgba(255,255,255,0.72);
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.08);
}

@media (max-width: 1100px) {
  .dgs-city-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .dgs-city-section {
    padding: 70px 20px;
  }

  .dgs-city-grid {
    grid-template-columns: 1fr;
  }

  .dgs-city-card {
    min-height: auto;
  }
}

/* Numbered Steps */
.dgs-numbered-steps {
  list-style: none;
  padding: 0;
  margin: 28px 0;
  counter-reset: steps;
}

.dgs-numbered-steps li {
  counter-increment: steps;
  font-size: 17px;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.75;
  padding: 18px 20px 18px 64px;
  position: relative;
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  margin-bottom: 12px;
  transition: all 0.3s ease;
}

.dgs-numbered-steps li:hover {
  border-color: rgba(233, 30, 140, 0.3);
  background: rgba(255, 255, 255, 0.05);
}

.dgs-numbered-steps li::before {
  content: counter(steps);
  position: absolute;
  left: 20px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 13px;
  font-weight: 700;
  color: var(--brand-magenta);
  width: 28px;
  height: 28px;
  border: 1px solid rgba(233, 30, 140, 0.4);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Section Header */
.dgs-section-header {
  text-align: center;
  max-width: 900px;
  margin: 0 auto 48px;
}

.dgs-section-tag {
  display: inline-block;
  padding: 8px 20px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50px;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: rgba(255, 255, 255, 0.7);
  font-weight: 500;
}

.dgs-section-title {
  font-size: clamp(36px, 6vw, 54px);
  font-weight: 700;
  margin-bottom: 20px;
  line-height: 1.2;
}

.dgs-section-subtitle {
  font-size: 19px;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.8;
}

/* Pillars */
.dgs-pillars-section {
  padding: 82px 20px;
}

.dgs-pillars-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  max-width: 1180px;
  margin: 0 auto;
}

.dgs-pillar-card {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 3px solid transparent;
  border-image: var(--gradient-brand) 1;
  border-radius: 12px;
  padding: 34px;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
}

.dgs-pillar-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(233,30,140,0.05) 0%, rgba(255,107,53,0.05) 100%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.dgs-pillar-card:hover {
  background: rgba(255, 255, 255, 0.05);
  transform: translateY(-6px);
  box-shadow: 0 10px 40px rgba(233, 30, 140, 0.1);
}

.dgs-pillar-card:hover::before {
  opacity: 1;
}

.dgs-pillar-number {
  font-size: 13px;
  font-weight: 600;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 14px;
  letter-spacing: 1.5px;
}

.dgs-pillar-title {
  font-size: 23px;
  font-weight: 700;
  margin-bottom: 14px;
}

.dgs-pillar-description {
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.75;
  margin-bottom: 20px;
  font-size: 16px;
}

.dgs-pillar-list {
  list-style: none;
  padding: 0;
}

.dgs-pillar-list li {
  padding: 8px 0 8px 24px;
  position: relative;
  color: rgba(255, 255, 255, 0.72);
  font-size: 15px;
  line-height: 1.6;
}

.dgs-pillar-list li:before {
  content: "";
  position: absolute;
  left: 0;
  top: 17px;
  width: 12px;
  height: 2px;
  background: var(--gradient-brand);
}



/* Impact Cards */
.dgs-impact-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  margin: 34px 0;
  align-items: stretch;
}

.dgs-impact-card {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  padding: 30px 26px;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.dgs-impact-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--gradient-brand);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.dgs-impact-card:hover {
  transform: translateY(-6px);
  border-color: rgba(233, 30, 140, 0.35);
  box-shadow: 0 15px 50px rgba(233, 30, 140, 0.12);
}

.dgs-impact-card:hover::before {
  opacity: 1;
}

.dgs-impact-title {
  font-size: 19px;
  font-weight: 700;
  margin-bottom: 12px;
  color: #ffffff;
}

.dgs-impact-desc {
  font-size: 15px;
  color: rgba(255, 255, 255, 0.68);
  line-height: 1.75;
  margin-bottom: 16px;
}

.dgs-impact-metric {
  margin-top: auto;
  font-size: 13px;
  color: rgba(255,255,255,0.72);
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 14px;
}

.dgs-impact-link {
  display: inline-block;
  margin-top: 14px;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}

/* CTA Mid */
.dgs-cta-section {
  padding: 82px 20px;
  background: linear-gradient(135deg, rgba(233,30,140,0.05) 0%, rgba(185,30,140,0.05) 50%, rgba(255,107,53,0.05) 100%);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.dgs-cta-content {
  max-width: 900px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
  padding: 48px 38px;
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 24px;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.15);
}

.dgs-cta-title {
  font-size: clamp(34px, 6vw, 50px);
  font-weight: 700;
  margin-bottom: 20px;
}

.dgs-cta-description {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.78);
  margin-bottom: 32px;
  line-height: 1.8;
}

.dgs-cta-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  justify-content: center;
}

/* FAQ */
.dgs-faq-section {
  padding: 82px 20px;
}

.dgs-faq-container {
  max-width: 950px;
  margin: 0 auto;
}

.dgs-faq-item {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  margin-bottom: 20px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.dgs-faq-item:hover {
  border-color: rgba(233, 30, 140, 0.3);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
}

.dgs-faq-question {
  padding: 28px;
  font-size: 19px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
}

.dgs-faq-answer {
  padding: 0 28px 28px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.8;
  font-size: 17px;
  display: none;
}

.dgs-faq-item.active .dgs-faq-answer {
  display: block;
}

.dgs-faq-toggle {
  font-size: 24px;
  transition: transform 0.3s ease;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  flex-shrink: 0;
}

.dgs-faq-item.active .dgs-faq-toggle {
  transform: rotate(45deg);
}

/* Final CTA */
.dgs-final-cta {
  padding: 82px 20px;
  background: rgba(255, 255, 255, 0.01);
}

.dgs-final-cta-container {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.dgs-final-cta-container h2 {
  font-size: clamp(36px, 6vw, 54px);
  font-weight: 700;
  margin-bottom: 20px;
}

.dgs-final-cta-container > p {
  font-size: 19px;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 42px;
  line-height: 1.8;
}

.dgs-form-shortcode {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  padding: 42px;
  margin-bottom: 38px;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
}

.dgs-contact-info {
  display: flex;
  justify-content: center;
  gap: 18px;
  flex-wrap: wrap;
}

.dgs-contact-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 16px 24px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.85) !important;
  text-decoration: none;
  font-size: 16px;
  transition: all 0.3s ease;
}

.dgs-contact-item:hover {
  border-color: var(--brand-magenta);
  background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
  transform: translateY(-2px);
}

/* Fluent Form Dark Theme */
.dgs-form-shortcode .fluentform,
.dgs-form-shortcode form {
  text-align: left;
}

.dgs-form-shortcode .ff-el-group {
  margin-bottom: 18px;
}

.dgs-form-shortcode label,
.dgs-form-shortcode .ff-el-input--label label {
  color: rgba(255,255,255,0.82) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  margin-bottom: 8px !important;
}

.dgs-form-shortcode input,
.dgs-form-shortcode textarea,
.dgs-form-shortcode select,
.dgs-form-shortcode .ff-el-form-control {
  width: 100% !important;
  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  color: #ffffff !important;
  border-radius: 10px !important;
  min-height: 48px !important;
  padding: 13px 15px !important;
  box-shadow: none !important;
  outline: none !important;
}

.dgs-form-shortcode textarea,
.dgs-form-shortcode textarea.ff-el-form-control {
  min-height: 120px !important;
}

.dgs-form-shortcode input::placeholder,
.dgs-form-shortcode textarea::placeholder {
  color: rgba(255,255,255,0.42) !important;
}

.dgs-form-shortcode input:focus,
.dgs-form-shortcode textarea:focus,
.dgs-form-shortcode select:focus,
.dgs-form-shortcode .ff-el-form-control:focus {
  border-color: var(--brand-magenta) !important;
  box-shadow: 0 0 0 3px rgba(233,30,140,0.14) !important;
}

.dgs-form-shortcode .ff-btn-submit,
.dgs-form-shortcode button[type="submit"],
.dgs-form-shortcode input[type="submit"] {
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta)) !important;
  background-size: 400% 400% !important;
  color: #ffffff !important;
  border: 0 !important;
  border-radius: 10px !important;
  padding: 15px 30px !important;
  font-weight: 700 !important;
  font-size: 16px !important;
  cursor: pointer !important;
  animation: gradientPulse 4s ease infinite !important;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.28) !important;
}

.dgs-form-shortcode .ff-btn-submit:hover,
.dgs-form-shortcode button[type="submit"]:hover,
.dgs-form-shortcode input[type="submit"]:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 42px rgba(233, 30, 140, 0.38) !important;
}

.dgs-form-shortcode .ff_form_title,
.dgs-form-shortcode .fluentform .ff-form-title {
  display: none !important;
}

/* LLM Upgrade / Proof Section */
.llm-upgrade,
.llm-upgrade * {
  box-sizing: border-box;
  font-family: 'DM Sans', Arial, sans-serif;
}

.llm-upgrade {
  --bg: #07060D;
  --bg2: #0D0B18;
  --bg3: #141122;
  --silver: #F0EDF8;
  --body: #C8C5D8;
  --muted: #8A87A0;
  --dim: #5C596E;
  --line: rgba(255,255,255,.08);
  --ln2: rgba(255,255,255,.15);
  --green: #22C55E;
  color: var(--body);
  background: #000000;
}

.llm-upgrade img {
  display: block;
  max-width: 100%;
}

.llm-upgrade .w {
  max-width: 1360px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .ws {
  max-width: 860px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .sec {
  padding: 72px 0;
  border-bottom: 1px solid var(--line);
}

.llm-upgrade .sh {
  text-align: center;
  margin-bottom: 38px;
}

.llm-upgrade .ew {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.llm-upgrade .ewl {
  width: 18px;
  height: 1px;
  background: linear-gradient(90deg,#E8612A,#6247B0);
}

.llm-upgrade .gt,
.llm-upgrade .ewt {
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .sh h2 {
  font-size: clamp(30px,4vw,48px);
  line-height: 1.08;
  letter-spacing: -1.5px;
  color: var(--silver);
  margin: 0 0 10px;
}

.llm-upgrade .sh p {
  font-size: 15px;
  color: var(--muted);
  max-width: 780px;
  margin: 0 auto;
  line-height: 1.7;
}

@keyframes llmGradientShift {
  0%,100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.llm-upgrade .bento-row {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 14px;
}

.llm-upgrade .bi {
  min-height: 260px;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--bg2);
  position: relative;
  cursor: pointer;
  transition: .28s;
}

.llm-upgrade .bi:hover {
  transform: translateY(-5px);
  border-color: var(--ln2);
  box-shadow: 0 20px 50px rgba(0,0,0,.5);
}

.llm-upgrade .bi img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.llm-upgrade .bio {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 14px 16px;
  background: linear-gradient(to top,rgba(7,6,13,.94),transparent);
}

.llm-upgrade .bipill {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 5px;
  background: linear-gradient(135deg,#E8612A,#C43F7A);
  color: #fff;
  margin-bottom: 5px;
}

.llm-upgrade .bittl {
  font-size: 13px;
  font-weight: 500;
  color: var(--silver);
}

.llm-upgrade .bizoom {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 30px;
  height: 30px;
  border-radius: 7px;
  background: rgba(0,0,0,.55);
  border: 1px solid var(--ln2);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: .2s;
}

.llm-upgrade .bi:hover .bizoom {
  opacity: 1;
}

.llm-upgrade .bizoom svg {
  width: 13px;
  height: 13px;
  stroke: #fff;
  stroke-width: 2;
  fill: none;
}


/* LLM-Style Case Studies */
.llm-upgrade .csg {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.llm-upgrade .csc {
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--bg2);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  transition: .3s;
}

.llm-upgrade .csc::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,#E8612A,#C43F7A,#6247B0);
  z-index: 2;
}

.llm-upgrade .csc:hover {
  transform: translateY(-7px);
  border-color: var(--ln2);
  box-shadow: 0 28px 70px rgba(0,0,0,.5);
}

.llm-upgrade .csss {
  height: 190px;
  overflow: hidden;
  position: relative;
}

.llm-upgrade .csss::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 55px;
  background: linear-gradient(to top,var(--bg2),transparent);
}

.llm-upgrade .csss img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.llm-upgrade .csbody {
  padding: 22px 26px 24px;
}

.llm-upgrade .cslogo {
  height: 30px;
  margin-bottom: 13px;
}

.llm-upgrade .cslogo img {
  height: 100%;
  width: auto;
  object-fit: contain;
}

.llm-upgrade .cstag {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 4px 11px;
  border-radius: 100px;
  margin-bottom: 12px;
  background: rgba(232,97,42,.1);
  color: #E8612A;
  border: 1px solid rgba(232,97,42,.2);
}

.llm-upgrade .csbody h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.4px;
  color: var(--silver);
  margin: 0 0 9px;
  line-height: 1.3;
}

.llm-upgrade .csbody > p {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.68;
  margin: 0 0 18px;
}

.llm-upgrade .csnums {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 9px;
  margin-bottom: 14px;
}

.llm-upgrade .cnum {
  text-align: center;
  padding: 12px 5px;
  background: rgba(255,255,255,.03);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.llm-upgrade .cnum strong {
  display: block;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .cnum span {
  font-size: 10px;
  color: var(--dim);
  text-transform: uppercase;
}

.llm-upgrade .csview {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 500;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .csft {
  padding: 12px 26px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  gap: 9px;
}

.llm-upgrade .csav {
  width: 25px;
  height: 25px;
  border-radius: 6px;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg,#E8612A,#C43F7A);
  color: #fff;
  flex-shrink: 0;
}

.llm-upgrade .csfn {
  font-size: 12px;
  color: var(--muted);
}

.llm-upgrade .cstm {
  margin-left: auto;
  font-size: 11px;
  color: var(--dim);
}

.llm-upgrade .csc:focus {
  outline: 2px solid rgba(196,63,122,.55);
  outline-offset: 3px;
}

@media(max-width:860px) {
  .llm-upgrade .csg {
    grid-template-columns: 1fr;
  }
}


/* Brand Presence & Media Visibility */
.llm-upgrade .mqwrap {
  position: relative;
  overflow: hidden;
  padding: 8px 0;
  -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
  mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
}

.llm-upgrade .mqtrack {
  display: flex;
  gap: 12px;
  width: max-content;
  animation: llmMarquee 120s linear infinite;
}

.llm-upgrade .mqtrack:hover {
  animation-play-state: paused;
}

@keyframes llmMarquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.llm-upgrade .nc {
  flex-shrink: 0;
  width: 168px;
  height: 74px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.02);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 9px 13px;
  overflow: hidden;
  transition: all .25s ease;
}

.llm-upgrade .nc:hover {
  border-color: rgba(196,63,122,.28);
  background: rgba(196,63,122,.04);
  transform: translateY(-3px);
}

.llm-upgrade .nc img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: .72;
  filter: brightness(.85) saturate(.55);
  transition: all .25s ease;
}

.llm-upgrade .nc:hover img {
  opacity: 1;
  filter: brightness(1.05) saturate(.95);
}

/* Lightbox */
.llm-upgrade .lb {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: rgba(3,2,9,.96);
  backdrop-filter: blur(22px);
  display: none;
  flex-direction: column;
}

.llm-upgrade .lb.on {
  display: flex;
}

.llm-upgrade .lbtop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-bottom: 1px solid var(--line);
  background: rgba(13,11,24,.97);
}

.llm-upgrade .lbtl {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.llm-upgrade .lbpill {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 5px;
  background: linear-gradient(135deg,#E8612A,#C43F7A);
  color: #fff;
  white-space: nowrap;
}

.llm-upgrade .lbttl {
  font-size: 15px;
  font-weight: 500;
  color: var(--silver);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.llm-upgrade .lbcount {
  font-size: 12px;
  color: var(--muted);
  margin-right: 8px;
}

.llm-upgrade .lbactions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.llm-upgrade .lbbtn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255,255,255,.07);
  border: 1px solid var(--ln2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--muted);
  font-size: 18px;
  transition: .25s;
}

.llm-upgrade .lbbtn:hover {
  color: #ffffff;
  border-color: rgba(255,255,255,.35);
  background: rgba(255,255,255,.12);
}

.llm-upgrade .lbbody {
  flex: 1;
  overflow-x: auto;
  overflow-y: hidden;
  display: flex;
  align-items: center;
  padding: 24px;
  gap: 20px;
  scroll-behavior: smooth;
}

.llm-upgrade .lbimg {
  height: calc(100vh - 120px);
  width: auto;
  max-width: none;
  border-radius: 12px;
  border: 1px solid var(--ln2);
  box-shadow: 0 24px 60px rgba(0,0,0,.6);
  object-fit: contain;
  margin: 0 auto;
}

/* Finished Modal CSS */
.llm-upgrade .modal {
  position: fixed;
  inset: 0;
  background: rgba(3,2,9,.92);
